import React, { useState, useEffect } from "react";
import { Helmet } from "react-helmet-async";

const translations = {
  de: {
    title: "Datenschutzerklärung",
    intro: "Wir nehmen den Schutz Ihrer persönlichen Daten ernst. Diese Erklärung erläutert, wie wir Daten verarbeiten.",
    data: "Wir erheben Name, E-Mail, Adresse bei Bestellungen. Rechtsgrundlage: Art. 6 Abs. 1 b DSGVO.",
    rights: "Sie haben Rechte auf Auskunft, Löschung etc. Kontakt: UrsulaHeinke@gmx.de",
    cookies: "Wir nutzen Cookies für Funktionalität. Sie können diese ablehnen."
  }
};

export default function Datenschutz() {
  const [language, setLanguage] = useState("de");
  const t = translations[language];

  useEffect(() => {
    const storedLang = localStorage.getItem("language") || "de";
    setLanguage(storedLang);
  }, []);

  return (
    <section className="py-20 px-6 bg-slate-900 min-h-screen text-indigo-100">
      <Helmet>
        <title>{t.title} | Ursula Heinke</title>
        <meta name="description" content={t.intro} />
        <link rel="canonical" href={window.location.href} />
      </Helmet>
      <div className="max-w-4xl mx-auto bg-slate-800/50 rounded-2xl p-8 shadow-lg backdrop-blur-sm">
        <h1 className="text-4xl font-bold text-blue-400 mb-6">{t.title}</h1>
        <p className="mb-4">{t.intro}</p>
        <p className="mb-2">{t.data}</p>
        <p className="mb-2">{t.rights}</p>
        <p className="mb-2">{t.cookies}</p>
        {/* Hier können noch detailliertere Datenschutzinfos ergänzt werden */}
      </div>
    </section>
  );
}
